@GameTest
public void testMyBlock(GameTestHelper helper) {
    // Place a block
    helper.setBlock(new BlockPos(0, 1, 0), ModBlocks.MY_BLOCK.get());

    // Spawn entity
    helper.spawnEntity(new ItemEntity(helper.getLevel(), 0, 2, 0, new ItemStack(Items.DIAMOND)));

    // Assert success
    helper.succeedWhen(() -> {
        helper.getBlockState(new BlockPos(0, 1, 0)).is(ModBlocks.MY_BLOCK.get());
    });
}
